339	\centering
340	\small
341	\begin{tabular}{lcccrrr}
342	\toprule
343	\textbf{Config} & $w_1$ & $w_2$ & $w_3$ & \textbf{NoF} & \textbf{WRR} & \textbf{RC} \\
344	\midrule
345	Default & .30 & .20 & .50 & 16.2 & 53.8 & 0.83 \\
346	R1/R3 rev. & .50 & .20 & .30 & 15.4 & 52.1 & 0.82 \\
347	R1 dom. & .60 & .10 & .30 & 17.3 & 49.6 & 0.79 \\
